import { Column, Hooks } from 'react-table';

import {
  format,
  Unit,
  ConvertibleUnit,
  FormatOptions,
} from '@dynatrace-sdk/units';

/**
 * Apparently it is not possible to override a type in react-table-config.d.ts unless it's an interface.
 */
type ExtendedColumn = Column & {
  formatter: FormatOptions<Unit, ConvertibleUnit>;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  Cell?: any;
  columns?: ExtendedColumn[];
};

/* Format column cell */
function formatColumnCell(column: ExtendedColumn) {
  return (column.Cell = ({ value }: { value: number }) =>
    format(Number(value), column.formatter));
}

/** Formats cell value based on the options specified in the column definition */
function applyCellFormatting(columns: ExtendedColumn[]) {
  const formattedColumns = columns;

  for (const column of formattedColumns) {
    if (column.formatter) {
      formatColumnCell(column);
    }
    if (column.columns) {
      for (const subCol of column.columns) {
        if (subCol.formatter) {
          formatColumnCell(subCol);
        }
      }
    }
  }
  return formattedColumns;
}

/** Table hook that enables formatting table values */
export function useFormatting(hooks: Hooks): void {
  // Extended types do not overlap with the comunity types.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  hooks.columns.push(applyCellFormatting as any);
}
